// worker/email.js
async function sendEmail(env, { to, subject, text, html = null }, source = "worker") {
  const apiKey = String(env.RESEND_API_KEY || "").trim();
  const from = String(env.RESEND_FROM_EMAIL || "").trim();
  if (!apiKey || !from) {
    console.warn(`[${source}] email skipped: configure RESEND_API_KEY and RESEND_FROM_EMAIL on the Worker.`);
    return false;
  }
  try {
    const response2 = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        from,
        to: Array.isArray(to) ? to : [to],
        subject,
        text,
        html: html || renderPrimeMarketsEmail({ title: subject, body: text })
      })
    });
    if (!response2.ok) {
      console.error(`[${source}] Resend rejected email:`, response2.status, (await response2.text()).slice(0, 500));
      return false;
    }
    return true;
  } catch (error) {
    console.error(`[${source}] Resend delivery failed:`, error?.message || error);
    return false;
  }
}
__name(sendEmail, "sendEmail");
async function sendUserEmail(env, userId, message, source = "worker") {
  if (!String(env.RESEND_API_KEY || "").trim() || !String(env.RESEND_FROM_EMAIL || "").trim()) {
    return sendEmail(env, { ...message, to: [] }, source);
  }
  try {
    const user = await env.DB.prepare("SELECT email FROM auth_users WHERE id = ?").bind(userId).first();
    if (!user?.email) {
      console.warn(`[${source}] email skipped: user email not found.`);
      return false;
    }
    return await sendEmail(env, { ...message, to: user.email }, source);
  } catch (error) {
    console.error(`[${source}] recipient lookup failed:`, error?.message || error);
    return false;
  }
}
